BEGIN READ ONLY;
SET LOCAL statement_timeout='30s'; SET LOCAL lock_timeout='3s'; SET LOCAL jit=off;
WITH base AS MATERIALIZED(SELECT ts_code FROM raw_tushare.stock_basic WHERE ts_code !~ '^(200|900)' AND list_status IN('L','P') AND list_date<=DATE '2026-10-30' AND(delist_date IS NULL OR delist_date>DATE '2026-10-30') AND ts_code NOT IN('002717.SZ','002827.SZ','601326.SH','605258.SH','688121.SH','688496.SH')),m AS MATERIALIZED(SELECT h.sector_code,h.industry_level,h.root_sector_code,h.parent_sector_code,m.con_code FROM core_serving.dc_member m JOIN core_serving.wealth_sector_hierarchy h ON h.sector_code=m.ts_code WHERE m.trade_date=DATE '2026-10-30'),leaf AS MATERIALIZED(SELECT DISTINCT m.con_code,m.root_sector_code,m.parent_sector_code FROM m JOIN base a ON a.ts_code=m.con_code WHERE m.industry_level=3),q AS(SELECT count(*) leaf_codes,count(*) FILTER(WHERE NOT EXISTS(SELECT 1 FROM m WHERE m.industry_level=1 AND m.con_code=l.con_code)) direct_root_absent,count(*) FILTER(WHERE NOT EXISTS(SELECT 1 FROM m WHERE m.industry_level=2 AND m.con_code=l.con_code)) direct_parent_absent,count(*) FILTER(WHERE EXISTS(SELECT 1 FROM m WHERE m.industry_level=1 AND m.con_code=l.con_code AND m.sector_code<>l.root_sector_code)) root_disagreement,count(*) FILTER(WHERE EXISTS(SELECT 1 FROM m WHERE m.industry_level=2 AND m.con_code=l.con_code AND m.sector_code<>l.parent_sector_code)) parent_disagreement FROM leaf l)
SELECT jsonb_build_object('section','leaf_direct_mapping_agreement','as_of',current_timestamp,'data',to_jsonb(q)) FROM q;
COMMIT;
BEGIN READ ONLY;
SET LOCAL statement_timeout='30s'; SET LOCAL lock_timeout='3s'; SET LOCAL jit=off;
WITH q AS(SELECT ts_code,end_date,fix_assets_total IS NOT NULL total_present,fix_assets IS NOT NULL old_present,CASE WHEN fix_assets IS NOT NULL AND fix_assets_total IS NOT NULL THEN fix_assets=fix_assets_total ELSE NULL END fields_equal FROM core_serving.equity_balancesheet WHERE ts_code IN('600519.SH','601668.SH','601138.SH') AND end_date IN(DATE '2024-09-30',DATE '2025-09-30',DATE '2026-09-30') ORDER BY ts_code,end_date LIMIT 20)
SELECT jsonb_build_object('section','fixed_assets_bounded_samples','as_of',current_timestamp,'data',jsonb_agg(to_jsonb(q))) FROM q;
COMMIT;
